export function summarizeCart(items: Array<{ price: number; quantity: number; taxable?: boolean }>, taxRate: number) {
  let subtotal = 0;
  let taxableTotal = 0;
  for (const item of items) {
    const line = item.price * item.quantity;
    subtotal += line;
    if (item.taxable) taxableTotal += line;
  }
  const tax = taxableTotal * taxRate;
  return { subtotal, tax, total: subtotal + tax };
}
